"""Extract local Blood zombie SFX and prepare the user's music with a real crossfade."""
from pathlib import Path
import json, struct, wave, hashlib, subprocess, re
import numpy as np
from install_blood_cultist_voices import Rff, BLOOD, MOD

def main():
 rff=Rff(BLOOD/'sounds.rff'); rows=[]; header=[]
 events={1100:'Rise',1101:'Swipe',1102:'Step',1103:'Alert',1104:'Idle',1105:'Idle',1106:'Pain',1107:'Death',1108:'Death',1109:'Death',1200:'Alert',1201:'Idle',1202:'Pain',1203:'Attack',1204:'Death',1205:'Death',1206:'Death',1207:'Swipe'}
 selection=MOD/'zombie-sound-selection.json'
 disabled=set(json.loads(selection.read_text())['disabled_ids']) if selection.exists() else set()
 out=MOD/'sound/blood/zombie';out.mkdir(parents=True,exist_ok=True)
 for ident,event in events.items():
  if ident in disabled:continue
  entry=rff.byid['SFX',ident];sfx=rff.read(entry);volume,pitch,_,fmt,_=struct.unpack_from('<5i',sfx)
  rawname=bytes(sfx[20:]).split(b'\0')[0].decode();raw=rff.read(rff.byname['RAW',rawname.upper()]);rate=([11025]*5+[22050]*4+[44100]*4)[fmt]
  step=rate*pitch/65536/22050;positions=np.arange(0,len(raw),step);samples=np.rint(np.interp(positions,np.arange(len(raw)),np.frombuffer(raw,dtype=np.uint8).astype(float)-128)*256).astype('<i2')
  target=out/f'sfx_{ident}.wav'
  with wave.open(str(target),'wb') as w:w.setparams((1,2,22050,0,'NONE','not compressed'));w.writeframes(samples.tobytes())
  name=f'blood/zombie/sfx_{ident}.wav';duration=len(samples)/22050
  rows.append(dict(id=ident,name=entry[3],event=event,path='sound/'+name,duration=duration,sha256=hashlib.sha256(target.read_bytes()).hexdigest()))
  header.append(f'{{"{name}",{duration:.6f}f,ZombieVoiceEvent::{event}}},')
 (MOD/'source/blood_zombie_assets.h').write_text('// Generated by install_zombie_music.py\nenum class ZombieVoiceEvent {Rise,Swipe,Step,Alert,Idle,Pain,Death,Attack};\nstruct ZombieVoiceClip{const char* path;float duration;ZombieVoiceEvent event;};\nstatic const ZombieVoiceClip zombieVoiceClips[]={\n'+'\n'.join(header)+'\n};\n')
 (MOD/'blood-zombie-sounds.json').write_text(json.dumps(dict(archive=str(BLOOD/'sounds.rff'),disabled_ids=sorted(disabled),sources=['https://github.com/NBlood/NBlood/blob/master/source/blood/src/aizomba.cpp','https://github.com/NBlood/NBlood/blob/master/source/blood/src/aizombf.cpp'],clips=rows),indent=2))
 source=Path('C:/Users/bill/Documents/myFuneral/Exported/myFuneral Edit 1 Export 1.mp3');dest=MOD/'sound/music';dest.mkdir(parents=True,exist_ok=True)
 ffmpeg=Path('C:/Users/bill/AppData/Local/CapCut/Apps/9.3.0.3970/ffmpeg.exe');decoded=MOD/'diagnostics/music-decoded.wav';decoded.parent.mkdir(exist_ok=True)
 def measure(path):
  result=subprocess.run([str(ffmpeg),'-hide_banner','-nostats','-i',str(path),'-af','loudnorm=I=-16:TP=-1.5:LRA=11:print_format=json','-f','null','-'],capture_output=True,text=True,check=True)
  return json.loads(re.findall(r'\{[^{}]*"input_i"[^{}]*\}',result.stderr,re.S)[-1])
 measured=measure(source)
 normalization='loudnorm=I=-16:TP=-1.5:LRA=11:measured_I={input_i}:measured_TP={input_tp}:measured_LRA={input_lra}:measured_thresh={input_thresh}:offset={target_offset}:linear=true'.format(**measured)
 subprocess.run([str(ffmpeg),'-v','error','-y','-i',str(source),'-af',normalization,'-ar','44100','-ac','2','-c:a','pcm_s16le',str(decoded)],check=True)
 master=dest/'myfuneral_mastered.mp3'
 subprocess.run([str(ffmpeg),'-v','error','-y','-i',str(decoded),'-c:a','mp3_mf','-b:a','320k','-id3v2_version','3','-metadata','title=myFuneral - Masterizado',str(master)],check=True)
 mastered=measure(master)
 assert -17<float(mastered['input_i'])<-15,mastered
 assert float(mastered['input_tp'])<=-1.0,mastered
 with wave.open(str(decoded),'rb') as w:pcm=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2).astype(np.float64)/32768
 fade=6*44100;theta=np.linspace(0,np.pi/2,fade)[:,None];pcm[-fade:]=pcm[-fade:]*np.cos(theta)+pcm[:fade]*np.sin(theta)
 peak=float(np.max(np.abs(pcm)));gain=min(1,.98/max(peak,1e-9));encoded=np.rint(pcm*gain*32767).astype('<i2');target=dest/'myfuneral_loop.wav'
 with wave.open(str(target),'wb') as w:w.setparams((2,2,44100,0,'NONE','not compressed'));w.writeframes(encoded.tobytes())
 # smpl infinite forward loop starts after the head already heard in the crossfade.
 smpl=struct.pack('<15I',0,0,round(1e9/44100),60,0,0,0,1,0,0,0,fade,len(pcm)-1,0,0)
 data=bytearray(target.read_bytes());data+=b'smpl'+struct.pack('<I',len(smpl))+smpl;struct.pack_into('<I',data,4,len(data)-8);target.write_bytes(data)
 seam=np.abs(encoded[-1].astype(int)-encoded[fade].astype(int));assert max(seam)<3000,seam
 report=dict(source=str(source),source_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),mastered_mp3='sound/music/myfuneral_mastered.mp3',mastered_sha256=hashlib.sha256(master.read_bytes()).hexdigest(),original_loudness=measured,mastered_mp3_loudness=mastered,mastering_target=dict(integrated_lufs=-16,true_peak_dbtp=-1.5,lra=11),path='sound/music/myfuneral_loop.wav',sha256=hashlib.sha256(data).hexdigest(),frames=len(pcm),rate=44100,crossfade_seconds=6,loop_start_frame=fade,gain=gain,seam_delta_pcm=seam.tolist(),duration=len(pcm)/44100)
 (MOD/'music-loop.json').write_text(json.dumps(report,indent=2));print(json.dumps(dict(sounds=len(rows),music=report),indent=2))
if __name__=='__main__':main()
